package edu.gcu.cst339.lab2_chinook_api.playlist;

/**
 * Data transfer object used as the JSON request and response body for playlists.
 *
 * @param playlistId the playlist ID; generated by the database, so it is
 *                   ignored on create and taken from the URL on update
 * @param name       the playlist name (at most 120 characters)
 */
record PlaylistDto(
    Integer playlistId,
    String name
) {
    /**
     * Converts a playlist entity into a DTO.
     *
     * @param playlist the entity to convert
     * @return a DTO containing the entity's ID and name
     */
    static PlaylistDto fromEntity(Playlist playlist) {
        return new PlaylistDto(
            playlist.getPlaylistId(), 
            playlist.getName()
        );
    }
}